 */
export function isPinnedQuickItem(pinned, item) {
  const key = getQuickPinKey(item);
  if (!key) return false;
  const source = Array.isArray(pinned) ? pinned : [];
  return source.some((entry) => getQuickPinKey(entry) === key);
