      const maxKey = def.maxKey;
      if (Object.prototype.hasOwnProperty.call(next, valueKey)) state[valueKey] = Number(next[valueKey]);
      if (Object.prototype.hasOwnProperty.call(next, maxKey)) state[maxKey] = Number(next[maxKey]);
